// CSD_RATIONALE_BEGIN
// SMILES isocyanate CSD — fix attempt 39's syntax collapse while improving over attempt 9.
//
// Diagnosis of attempt 39 failure (4% accuracy, 4% syntax):
//   minSpanLength=10 caused the model to extend O=C=N-format SMILES past valid completion
//   points indefinitely. The N=C=O substring check never fires for the model's O=C=N format,
//   so the "keep extending" branch ran with 10 required tokens before considering closure.
//   The model, anchored on 4-pyridyl (aromatic) guidance, generated polyphenyl chains
//   until ring numbers exceeded 9 (C10, C11...) — producing invalid SMILES. 96/100 invalid.
//
// Root cause of attempt 9's 20% ceiling:
//   The 10 guidance examples (cyclohexyl, benzyl, naphthyl, pyridyl, etc.) are common
//   isocyanates likely in the exemplar set. The model generates those or close relatives,
//   which score 0 as exemplars. Only ~20% of runs deviate enough to generate novel structures.
//
// Two targeted changes from proven attempt 9:
//   1. minSpanLength = 5 (same as attempt 9, NOT 10 — the proven safe value).
//   2. Replace 10 common guidance examples with 6 UNUSUAL NON-AROMATIC isocyanates:
//      cyclopropyl, cyclobutyl, 1,1-difluoroethyl, 2-methoxyethyl, cyanomethyl, sec-butyl.
//      Non-aromatic: eliminates polyphenyl chain failure mode entirely.
//      Unusual: pushes model into novel chemical space → higher non-exemplar rate.
//   3. Add maxSpanLength=20 safety cap: close at first complete parse when span ≥ 20 tokens
//      regardless of N=C=O substring, preventing any monster SMILES from forming.
//
// Kept from attempt 9 (proven mechanisms):
//   - SafePenalizedConstrainedStep early (penalize ["C","CC","O"] 4.0) for diverse openers
//   - SafeTemperatureConstrainedStep T=1.6 mid-phase for diversity
//   - GroupBoostedConstrainedStep late-phase (≥18 tokens)
//   - N=C=O check (O=C=N format never fires) → "always extend" diversity mechanism
//   - CloseSpanWithinBudget fallback
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity): insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   OpenConstrainedSpan: sets currentConstrainedOut:=[], which satisfies
//     parser.IsValidPrefix([]) by method precondition. ✓
//
//   Branch "IsComplete+length>=5+(hasNCO>0 or length>=20)" — CloseConstrainedSpan:
//     sets insideConstrainedOut:=false making the implication vacuous; currentConstrainedOut:=[]. ✓
//
//   Branch "IsComplete+length>=5+extend" (SafeTemperatureConstrainedStep T=1.6):
//     hard-masks to parser-valid tokens plus EOS; if EOS we break without appending;
//     otherwise AppendConstrainedToken preserves IsValidPrefix by its postcondition. ✓
//
//   Branch "else" (SafePenalized / SafeTemperature / GroupBoosted): all three helpers
//     hard-mask to parser-valid tokens plus EOS. AppendConstrainedToken preserves
//     IsValidPrefix. Inner EOS-close is gated on IsCompletePrefix holding, then
//     CloseConstrainedSpan makes the implication vacuous. ✓
//
//   Post-loop CloseSpanWithinBudget: postcondition guarantees insideOut ==> IsValidPrefix(currentOut). ✓
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
//   OpenConstrainedSpan: appends "<<" (|generated|+1) and steps+1. Preserved. ✓
//
//   Complete+length>=5+close (CloseConstrainedSpan): appends ">>" (|generated|+1), steps+1.
//     Loop guard ensures steps < maxSteps so steps+1 <= maxSteps. Preserved. ✓
//
//   Complete+length>=5+extend: one step (steps+1); AppendConstrainedToken adds at most
//     1 token; EOS adds 0 to |generated|. Preserved. ✓
//
//   Else-branch: one step (steps+1); AppendConstrainedToken adds at most 1 token to
//     |generated|. Inner EOS-close is guarded by steps<maxSteps, adds one more step
//     and ">>" — total steps+2, |generated|+1 at most, within budget. Preserved. ✓
//
//   CloseSpanWithinBudget: closeBudget=maxSteps-steps; its postcondition gives
//     |cg|<=|generated|+closeBudget<=|generatedPrefix|+maxSteps; steps:=maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate exactly one novel SMILES for an isocyanate (contains N=C=O or O=C=N group). Use unusual, non-exemplar structures. Orientation examples only — generate something DIFFERENT: O=C=NC1CC1 (cyclopropyl), O=C=NC1CCC1 (cyclobutyl), O=C=NC(F)(F)C (1,1-difluoroethyl), O=C=NCCOC (2-methoxyethyl), O=C=NCC#N (cyanomethyl), O=C=NC(C)CC (sec-butyl). Output ONLY a single SMILES string with no explanation.");

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

var minSpanLength: nat := 5;
var maxSpanLength: nat := 20;
var tokenCount: nat := 0;
var commonTokens: seq<Token> := ["C", "CC", "O"];

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength {
    var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
    if hasNCO > 0 || |currentConstrainedOut| >= maxSpanLength {
      // Explicit N=C=O found OR structure is long enough — close the span
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      // O=C=N format, structure still short: keep extending for structural diversity
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.6, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        tokenCount := tokenCount + 1;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := eosToken;

    if tokenCount < 6 {
      // Early phase: penalize common openers for diversity
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, commonTokens, 4.0, eosToken
      );
    } else if tokenCount < 18 {
      // Mid phase: high temperature for structural variety
      next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.6, eosToken
      );
    } else {
      // Late phase: group-boosted to leverage caller vocabulary hints
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      // EOS: close if span is complete, long enough, and is a valid isocyanate format
      if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength && steps < maxSteps {
        var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
        var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
        if hasNCO > 0 || |currentConstrainedOut| >= maxSpanLength {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      tokenCount := tokenCount + 1;
    }
  }
}

if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

